def diagram(stem,labels,caption):
    out=D/'diagramas';out.mkdir(exist_ok=True);W,H=960,255
    svg=[f'<svg xmlns="http://www.w3.org/2000/svg" width="{W}" height="{H}" viewBox="0 0 {W} {H}"><rect width="960" height="255" fill="white"/>']
    pdf=out/(stem+'.pdf');c=canvas.Canvas(str(pdf),pagesize=(W,H));c.setFillColorRGB(1,1,1);c.rect(0,0,W,H,fill=1,stroke=0)
    for i,label in enumerate(labels):
        x=15+i*158;y=60;w=138;h=100
        svg.append(f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="3" fill="#EFF4F5" stroke="#163B50"/><text x="{x+12}" y="{y+23}" font-family="Arial" font-size="14" fill="#163B50">{i+1:02}</text>')
        c.setStrokeColorRGB(.086,.23,.31);c.setFillColorRGB(.937,.957,.961);c.rect(x,H-y-h,w,h,fill=1,stroke=1);c.setFillColorRGB(.086,.23,.31);c.setFont('Helvetica-Bold',14);c.drawString(x+12,H-y-23,f'{i+1:02}')
        for j,line in enumerate(label.split('\n')):
            svg.append(f'<text x="{x+w/2}" y="{y+51+j*20}" text-anchor="middle" font-family="Arial" font-size="15" fill="#163B50">{html.escape(line)}</text>');c.setFont('Helvetica',13);c.drawCentredString(x+w/2,H-y-51-j*20,line)
        if i<5:
            xa=x+w+2;xb=x+w+17;yy=y+h/2
            svg.append(f'<path d="M {xa} {yy} H {xb} M {xb-5} {yy-4} L {xb} {yy} L {xb-5} {yy+4}" fill="none" stroke="#163B50" stroke-width="2"/>');c.line(xa,H-yy,xb,H-yy);c.line(xb-5,H-yy+4,xb,H-yy);c.line(xb-5,H-yy-4,xb,H-yy)
    svg.append(f'<text x="15" y="211" font-family="Arial" font-size="14" fill="#425466">{html.escape(caption)}</text></svg>');(out/(stem+'.svg')).write_text(''.join(svg),encoding='utf-8');c.setFont('Helvetica',11);c.drawString(15,44,caption);c.save()
    p=pdfium.PdfDocument(str(pdf));p[0].render(scale=1.5).to_pil().save(out/(stem+'.png'))
    return 'documentacion/diagramas/'+stem+'.png'
